const items = $input.all();

const relevant = [
  'logiciel', 'développement', 'plateforme', 'données',
  'système', 'erp', 'business intelligence', 'cloud',
  'intelligence artificielle', 'application', 'web',
  'digital', 'refonte', 'solution logicielle', 'data',
  'sécurité informatique', 'réseau informatique', 'base de données',
  'datacenter', 'data center', 'microsoft', 'serveur'
];

const hardware = [
  'caméra', 'surveillance', 'tablette', 'imprimante',
  'câble', 'consommable', 'onduleur', 'climatiseur',
  'scanner', 'cartouche', 'graveur', 'photocopieur',
  'véhicule', 'mobilier', 'chaise', 'armoire'
];

const filtered = items.filter(item => {
  const desc = (item.json.description || '').toLowerCase();
  const isRelevant = relevant.some(k => desc.includes(k));
  const isHardware = hardware.some(k => desc.includes(k));
  return isRelevant && !isHardware;
});
$getWorkflowStaticData('global').filteredTenders = filtered.map(f => f.json);
// Save filtered tenders to pass through after Groq

return filtered.map((item, index) => ({
  json: {
    ...item.json,
    filter_index: index + 1
  }
}));

// Get Groq's response content
const groqContent = $input.first().json.choices[0].message.content;

// Parse the relevant indices from Groq
let indices = [];
try {
  const parsed = JSON.parse(groqContent);
  indices = parsed.relevant || [];
} catch(e) {
  const matches = groqContent.match(/\d+/g) || [];
  indices = matches.map(Number);
}

// Get tenders from the input item's data field
// The Aggregate node put them in $input.first().json.data
const tenders = $getWorkflowStaticData('global').filteredTenders || [];

// Debug: log what we have
console.log('Indices:', indices);
console.log('Tenders count:', tenders.length);

// Return relevant tenders
const result = indices
  .filter(i => i >= 1 && i <= tenders.length)
  .map(i => ({
    json: {
      ...tenders[i - 1],
      llm_classified: true,
      relevance_source: 'groq'
    }
  }));

if (result.length === 0) {
  return [{ json: { error: 'no_matches', indices, tenders_count: tenders.length } }];
}

return result;
